-- Rollback-only fixtures: no provider calls, paid jobs, uploads or public content retained.
begin;
create temp table checks(name text,passed boolean);
create function pg_temp.ok(v boolean,n text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'FAIL: %',n;end if;insert into checks values(n,true);end$$;
create function pg_temp.deny(k text,p jsonb,n text) returns void language plpgsql as $$begin begin perform public.ig_provider_reference(k,p);exception when others then insert into checks values(n,true);return;end;raise exception 'FAIL: %',n;end$$;
create function pg_temp.deny_prepare(p jsonb,n text) returns void language plpgsql as $$begin begin perform public.ig_provider_prepare(p);exception when others then insert into checks values(n,true);return;end;raise exception 'FAIL: %',n;end$$;
create function pg_temp.deny_content(p jsonb,n text) returns void language plpgsql as $$begin begin perform public.ig_save_content(p);exception when others then insert into checks values(n,true);return;end;raise exception 'FAIL: %',n;end$$;
do $$declare uid uuid;sid uuid;claims jsonb;mid uuid=gen_random_uuid();jid uuid;lease uuid=gen_random_uuid();cfg int;p jsonb;r jsonb;ref jsonb;content jsonb;k text=repeat('a',64);begin
 select u.id,s.id into uid,sid from auth.users u join auth.sessions s on s.user_id=u.id where u.email='akm@indiagully.com' order by s.created_at desc limit 1;
 if sid is null then raise exception 'Owner session required';end if;
 claims=jsonb_build_object('sub',uid,'session_id',sid,'aal','aal2','role','authenticated');perform set_config('request.jwt.claims',claims::text,true);
 update ig_private.integration_root set secret_hash=encode(extensions.digest(convert_to(k,'UTF8'),'sha256'),'hex');
 select version into cfg from ig_private.integration_config where id='runway';
 insert into public.ig_source_media(id,actor_id,practice,path,source_name,rights_reference,alt,preset,state) values(mid,uid,'horeca',uid||'/'||mid||'.jpg','SYSTEM TEST.jpg','Rollback-only fixture','SYSTEM TEST product','square','ready');
 p=jsonb_build_object('provider','runway','kind','image','practice','horeca','request_id',gen_random_uuid(),'config_version',cfg,'input',jsonb_build_object('kind','image','prompt','SYSTEM TEST enhancement of the exact product in @source','ratio','720:720','public_approved',true,'product_image_mode','enhance','product_title','SYSTEM TEST plate','reference_media_id',mid));
 perform pg_temp.ok(public.ig_public_media_path(mid) is null,'Source photograph remains unavailable publicly');
 perform pg_temp.deny_prepare(p||jsonb_build_object('input',(p->'input')-'reference_media_id'),'Enhancement requires a source image');
 perform pg_temp.deny_prepare(jsonb_set(p,'{practice}','"hospitality"'),'Product image jobs cannot cross practices');
 r=public.ig_provider_prepare(p);jid=(r->>'id')::uuid;
 perform pg_temp.ok(r->>'status'='queued','Private source can queue an enhancement');
 perform pg_temp.ok(public.ig_provider_prepare(p)->>'id'=jid::text,'Repeated image request cannot duplicate a paid job');
 ref=jsonb_build_object('id',jid,'lease_token',lease);
 perform pg_temp.deny(k,ref,'Queued job cannot request a source URL');
 update public.ig_provider_jobs set status='submitting',lease_token=lease,lease_until=now()+interval '2 minutes' where id=jid;
 perform pg_temp.deny('wrong',ref,'Source broker requires server authorisation');
 perform pg_temp.deny(k,jsonb_set(ref,'{lease_token}',to_jsonb(gen_random_uuid())),'Wrong worker lease cannot access source');
 perform pg_temp.ok(public.ig_provider_reference(k,ref)->>'path'=uid||'/'||mid||'.jpg','Valid leased worker can resolve private source');
 update public.ig_provider_jobs set lease_until=now()-interval '1 minute' where id=jid;perform pg_temp.deny(k,ref,'Expired worker lease is denied');
 update public.ig_provider_jobs set lease_until=now()+interval '2 minutes' where id=jid;
 update public.ig_profiles set status='suspended' where id=uid;perform pg_temp.deny(k,ref,'Revoked staff cannot process a source');update public.ig_profiles set status='active' where id=uid;
 update public.ig_source_media set practice='hospitality' where id=mid;perform pg_temp.deny(k,ref,'Source must belong to the job practice');update public.ig_source_media set practice='horeca' where id=mid;
 update public.ig_provider_jobs set status='ready',asset_key=jid||'.png',mime='image/png' where id=jid;
 content=jsonb_build_object('kind','product','practice','horeca','title','SYSTEM TEST image','slug','system-test-image-'||jid,'body','Rollback fixture only','public_data',jsonb_build_object('image','/images/generated/'||jid||'.png','image_alt','AI-enhanced product image · SYSTEM TEST'));
 perform pg_temp.deny_content(content,'Unreviewed creative cannot enter catalogue content');
 perform public.ig_provider_manage(jsonb_build_object('action','publish','id',jid,'reviewed',true));
 perform pg_temp.ok(public.ig_save_content(content)->>'kind'='product','Reviewed enhancement saves with correct disclosure');
 perform pg_temp.deny_content(jsonb_set(content,'{public_data,image_alt}','"Actual photograph"'),'AI disclosure cannot be removed');
 update public.ig_provider_jobs set input=(input-'reference_media_id')||'{"product_image_mode":"generate"}' where id=jid;
 perform pg_temp.deny_content(content,'Generated concept cannot be labelled as photo enhancement');
 perform pg_temp.ok(public.ig_save_content(jsonb_set(jsonb_set(content,'{slug}',to_jsonb('system-test-generated-'||jid)),'{public_data,image_alt}','"Illustrative AI-generated concept"'))->>'kind'='product','Generated concept saves with illustrative disclosure');
end $$;
select * from checks;
rollback;
